"""
api/data/portraits/ascii_cache.py
──────────────────────────────────
High-resolution ANSI TrueColor facial expression portraits and morphing engine for Marcus Webb.
Features:
  - Micro-character Half-Blocks ('▀'): 2 vertical TrueColor pixels per terminal character cell.
  - Compact dimensions (38 cols × 19 rows) ensuring full expression visibility without crowding terminal.
  - Tight face framing on eyes, brows, mouth, sweat, and facial wrinkles.
  - Smooth in-place cross-dissolve emotion morphing.
"""

import asyncio
import math
import os
import sys

# Enable ANSI and UTF-8 on Windows consoles
if sys.platform == "win32":
    try:
        os.system("")
        sys.stdout.reconfigure(encoding="utf-8")
    except Exception:
        pass

ACTIVE_STYLE = "halfblock"

def set_portrait_style(style: str):
    global ACTIVE_STYLE
    ACTIVE_STYLE = style.lower().strip()

def _normalize_behaviour(behaviour) -> str:
    name = str(getattr(behaviour, "value", behaviour)).lower()
    if name == "confess":
        return "confessing"
    return name

def render_halfblock_grid(grid) -> str:
    """Format 2D half-block grid into TrueColor ANSI escape strings."""
    lines = []
    for row in grid:
        line = "".join(f"\033[38;2;{rt};{gt};{bt};48;2;{rb};{gb};{bb}m▀" for rt, gt, bt, rb, gb, bb in row)
        lines.append(line + "\033[0m")
    return "\n".join(lines)

