# Default portrait dictionary referenced by nexus_demo.py
PORTRAITS = PORTRAITS_HALFBLOCK

def show_portrait(behaviour: str):
    """Print the static portrait for Marcus Webb in the active style."""
    name = _normalize_behaviour(behaviour)
    if ACTIVE_STYLE == "ascii":
        art = PORTRAITS_ASCII.get(name) or PORTRAITS_ASCII.get("cooperative")
    else:
        art = PORTRAITS_HALFBLOCK.get(name) or PORTRAITS_HALFBLOCK.get("cooperative")
    if art:
        print(f"\n{art}")

async def morph_portrait(from_behaviour: str, to_behaviour: str, frames: int = 10, delay: float = 0.035):
    """Smoothly in-place cross-dissolve between two emotional facial expressions."""
    from_name = _normalize_behaviour(from_behaviour)
    to_name = _normalize_behaviour(to_behaviour)

    if not sys.stdout.isatty():
        show_portrait(to_name)
        return

    if ACTIVE_STYLE == "ascii":
        show_portrait(to_name)
        return

    grid_a = PORTRAIT_GRIDS.get(from_name) or PORTRAIT_GRIDS.get("cooperative")
    grid_b = PORTRAIT_GRIDS.get(to_name) or PORTRAIT_GRIDS.get("cooperative")

    if not grid_a or not grid_b or from_name == to_name:
        show_portrait(to_name)
        return

    height = len(grid_a)
    width = len(grid_a[0])

    sys.stdout.write(f"\n{render_halfblock_grid(grid_a)}\n")
    sys.stdout.flush()
    await asyncio.sleep(0.03)

    for f in range(1, frames + 1):
        t = f / frames
        t_eased = (1.0 - math.cos(t * math.pi)) / 2.0

        sys.stdout.write(f"\033[{height}A\r")
        sys.stdout.flush()

        frame = []
        for y in range(height):
            row = []
            row_a = grid_a[y]
            row_b = grid_b[y]
            for x in range(width):
                rta, gta, bta, rba, gba, bba = row_a[x]
                rtb, gtb, btb, rbb, gbb, bbb = row_b[x]
                rt = int((1.0 - t_eased) * rta + t_eased * rtb)
                gt = int((1.0 - t_eased) * gta + t_eased * gtb)
                bt = int((1.0 - t_eased) * bta + t_eased * btb)
                rb = int((1.0 - t_eased) * rba + t_eased * rbb)
                gb = int((1.0 - t_eased) * gba + t_eased * gbb)
                bb = int((1.0 - t_eased) * bba + t_eased * bbb)
                row.append((rt, gt, bt, rb, gb, bb))
            frame.append(row)

        sys.stdout.write(render_halfblock_grid(frame) + "\n")
        sys.stdout.flush()
        await asyncio.sleep(delay)
